HARNESS_SOURCE = 'from pathlib import Path\nfrom datetime import datetime, timezone\nimport csv, hashlib, io, json, os, re, shutil, subprocess, sys, tempfile, traceback, zipfile\nimport xml.etree.ElementTree as ET\n\nPROJECT = Path(\'/home/ecs-user/projects/t1-agent\')\nCODE = PROJECT / \'code\'\nOUT = CODE / \'docs/acceptance/s4/selection-optimization/runtime-validation\'\nlabel = \'plan-sync-dry-run-\' + datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\')\nOUT.mkdir(parents=True, exist_ok=True)\n(OUT / (label + \'.harness.py\')).write_text(HARNESS_SOURCE, encoding=\'utf-8\')\nplan_names = [\'T1智能体开发计划.docx\', \'T1开发执行说明.docx\', \'当前版本.json\', \'开发计划.json\', \'开发阶段与验收.csv\', \'开发任务清单.csv\']\nplan_paths = [Path(\'方案/子任务T1\') / name for name in plan_names]\nhandoff_path = Path(\'code/docs/acceptance/s4/current-handoff.json\')\nscript_path = Path(\'code/scripts/record-s4-selection-progress.py\')\nreview_path = Path(\'code/docs/acceptance/s4/review-index.json\')\nreport_path = Path(\'code/docs/acceptance/s4/selection-optimization/report.json\')\nregistry_path = Path(\'code/docs/acceptance/s4/selection-optimization/experiment-register.json\')\ninputs = plan_paths + [handoff_path, script_path, review_path, report_path, registry_path]\noriginal_bytes = {str(path): (PROJECT / path).read_bytes() for path in inputs}\nsha = lambda raw: hashlib.sha256(raw).hexdigest()\noriginal_hashes = {path: sha(raw) for path, raw in original_bytes.items()}\ndef production_hashes():\n    return {str(p.relative_to(CODE)): sha(p.read_bytes()) for package in [\'agent\', \'contracts\'] for p in sorted((CODE / \'packages\' / package / \'src\').rglob(\'*\')) if p.is_file()}\nproduction_before = production_hashes()\nwork = Path(tempfile.mkdtemp(prefix=label + \'-workspace-\', dir=OUT))\nmirror = work / \'isolated-project\'\nresult = {\'engineering_synthetic\': True, \'real_experiment_still_in_progress\': True, \'real_paper_runs_completed_by_this_test\': 0,\n          \'medical_approval_granted_by_this_test\': False, \'source_script\': str(script_path), \'temporary_project\': str(mirror),\n          \'original_input_sha256_before\': original_hashes, \'copied_original_report_without_changing_statistics\': True,\n          \'AI_reference_contents_read\': False, \'API_calls\': 0, \'checks\': {}}\nstdout_logs = []\nsuccess = False\ndef require(condition, message):\n    if not condition:\n        raise AssertionError(message)\ndef canonical(value):\n    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(\',\', \':\')).encode()\ndef tree_hashes(base):\n    return {str(p.relative_to(base)): sha(p.read_bytes()) for p in sorted(base.rglob(\'*\')) if p.is_file()}\ndef compare_docx(relative):\n    before_raw = original_bytes[str(relative)]\n    after_raw = (mirror / relative).read_bytes()\n    with zipfile.ZipFile(io.BytesIO(before_raw)) as old, zipfile.ZipFile(io.BytesIO(after_raw)) as new:\n        old_infos, new_infos = old.infolist(), new.infolist()\n        require([i.filename for i in old_infos] == [i.filename for i in new_infos], f\'{relative}: ZIP member inventory/order changed\')\n        original_xml, updated_xml = old.read(\'word/document.xml\'), new.read(\'word/document.xml\')\n        other_count = 0\n        for old_info, new_info in zip(old_infos, new_infos):\n            if old_info.filename != \'word/document.xml\':\n                require(old.read(old_info) == new.read(new_info), f\'{relative}: other ZIP member content changed: {old_info.filename}\')\n                other_count += 1\n    delta = len(updated_xml) - len(original_xml)\n    require(delta > 0, f\'{relative}: no XML insertion found\')\n    prefix = 0\n    while prefix < min(len(original_xml), len(updated_xml)) and original_xml[prefix] == updated_xml[prefix]:\n        prefix += 1\n    candidates = [match.start() for match in re.finditer(rb\'<w:p(?:\\s[^>]*)?>\', updated_xml) if match.start() <= prefix]\n    position = next((index for index in reversed(candidates) if updated_xml[:index] + updated_xml[index + delta:] == original_xml), None)\n    require(position is not None, f\'{relative}: original XML bytes cannot be recovered by removing one paragraph insertion\')\n    inserted = updated_xml[position:position + delta]\n    ns = \'http://schemas.openxmlformats.org/wordprocessingml/2006/main\'\n    added = list(ET.fromstring(b\'<probe xmlns:w="\' + ns.encode() + b\'">\' + inserted + b\'</probe>\'))\n    require(len(added) == 8 and all(node.tag == \'{\' + ns + \'}p\' for node in added), f\'{relative}: insertion is not exactly 8 continuous paragraphs\')\n    old_body = ET.fromstring(original_xml).find(\'{\' + ns + \'}body\')\n    new_body = ET.fromstring(updated_xml).find(\'{\' + ns + \'}body\')\n    require(old_body is not None and new_body is not None and len(new_body) == len(old_body) + 8, f\'{relative}: unexpected body element count\')\n    title = \'\'.join(added[0].itertext())\n    require(\'S4可解释文本选择与Luna开发对照\' in title, f\'{relative}: unexpected appended title\')\n    return {\'path\': str(relative), \'before_sha256\': sha(before_raw), \'after_sha256\': sha(after_raw),\n            \'continuous_paragraphs_added\': len(added), \'insertion_offset_bytes\': position, \'inserted_xml_bytes\': delta,\n            \'original_document_xml_byte_identical_after_removing_one_insertion\': True,\n            \'all_other_zip_members_byte_identical\': True, \'other_zip_members_checked\': other_count}\ndef compare_plan_json(relative):\n    old = json.loads(original_bytes[str(relative)])\n    new = json.loads((mirror / relative).read_bytes())\n    require(set(old) == set(new), f\'{relative}: root key set changed\')\n    for key in old.keys() - {\'S4_engineering\', \'tasks\'}:\n        require(old[key] == new[key], f\'{relative}: non-S4 root object changed: {key}\')\n    allowed_s4 = {\'current_work\', \'selection_optimization\', \'experiment_limits_historical_only\', \'active_experiment_limits\',\n                  \'progress_record\', \'readable_report\', \'next_action\', \'status\', \'quality_status\', \'stage_passed\'}\n    old_s4, new_s4 = old[\'S4_engineering\'], new[\'S4_engineering\']\n    for key in old_s4.keys() | new_s4.keys():\n        if key not in allowed_s4:\n            require(key in old_s4 and key in new_s4 and old_s4[key] == new_s4[key], f\'{relative}: protected S4 field changed: {key}\')\n    old_tasks, new_tasks = old.get(\'tasks\', []), new.get(\'tasks\', [])\n    require(len(old_tasks) == len(new_tasks), f\'{relative}: task count changed\')\n    changed_tasks = []\n    for a, b in zip(old_tasks, new_tasks):\n        require(a[\'id\'] == b[\'id\'], f\'{relative}: task order/identity changed\')\n        if a[\'id\'] in [\'T1-R09\', \'T1-R10\', \'T1-R11\', \'T1-R12\']:\n            require({k:v for k,v in a.items() if k != \'engineering_progress\'} == {k:v for k,v in b.items() if k != \'engineering_progress\'}, f\'{relative}: task changed outside engineering_progress\')\n            if a != b:\n                changed_tasks.append(a[\'id\'])\n        else:\n            require(a == b, f\'{relative}: non-S4 task changed\')\n    protected = [\'S2_preparation\', \'S3_engineering\', \'S3_continuation_history\', \'stage_acceptances\', \'quality_thresholds_frozen\']\n    protected_hashes = {key: {\'before\': sha(canonical(old.get(key))), \'after\': sha(canonical(new.get(key)))} for key in protected}\n    require(all(pair[\'before\'] == pair[\'after\'] for pair in protected_hashes.values()), f\'{relative}: S2/S3/gate protection failed\')\n    selection = new_s4[\'selection_optimization\']\n    require(new_s4[\'stage_passed\'] is False and selection[\'stage_passed\'] is False and selection[\'S5_started\'] is False, f\'{relative}: stage/S5 flags invalid\')\n    require(selection[\'formal_model_selected\'] is False and selection[\'pathology_real_validation\'] is False and selection[\'AI_reference_is_not_gold\'] is True, f\'{relative}: approval/quality claims invalid\')\n    return {\'path\': str(relative), \'all_non_S4_root_objects_unchanged\': True, \'all_protected_S4_fields_unchanged\': True,\n            \'S2_S3_gates_sha256\': protected_hashes, \'task_changes_limited_to_S4_engineering_progress\': changed_tasks,\n            \'stage_passed\': False, \'S5_started\': False}\ndef compare_csv(relative):\n    def parse(raw):\n        reader = csv.DictReader(io.StringIO(raw.decode(\'utf-8-sig\'), newline=\'\'))\n        rows = list(reader)\n        return reader.fieldnames, rows\n    old_fields, old_rows = parse(original_bytes[str(relative)])\n    new_fields, new_rows = parse((mirror / relative).read_bytes())\n    require(old_fields == new_fields and len(old_rows) == len(new_rows), f\'{relative}: CSV structure changed\')\n    allowed_ids = {\'S4\'} if relative.name == \'开发阶段与验收.csv\' else {\'T1-R09\', \'T1-R10\', \'T1-R11\', \'T1-R12\'}\n    changed_cells = []\n    for index, (old, new) in enumerate(zip(old_rows, new_rows)):\n        for field in old_fields:\n            if old[field] != new[field]:\n                require(field == \'工程进度\' and old[old_fields[0]] in allowed_ids, f\'{relative}: unexpected changed cell\')\n                changed_cells.append({\'row\': index + 2, \'id\': old[old_fields[0]], \'column\': field})\n    require(changed_cells, f\'{relative}: no S4 progress cell changed\')\n    return {\'path\': str(relative), \'only_target_S4_progress_cells_changed\': True, \'changed_cells\': changed_cells,\n            \'all_other_cells_unchanged\': True}\ntry:\n    for relative, raw in original_bytes.items():\n        target = mirror / relative\n        target.parent.mkdir(parents=True, exist_ok=True)\n        target.write_bytes(raw)\n    registry = json.loads((mirror / registry_path).read_bytes())\n    synthetic_jobs = 0\n    for job in registry[\'jobs\']:\n        if job[\'independent_model_run\']:\n            job[\'status_before_engineering_synthetic_dry_run\'] = job[\'status\']\n            job[\'status\'] = \'engineering_synthetic_terminal_for_dry_run\'\n            job[\'engineering_synthetic_only\'] = True\n            synthetic_jobs += 1\n    synthetic_runtime = mirror / \'code/runtime-data/engineering-synthetic-plan-sync\'\n    synthetic_runtime.mkdir(parents=True)\n    (synthetic_runtime / \'active-owner.lock\').write_text(\'ENGINEERING SYNTHETIC ONLY: real experiment not terminated by this test.\\n\')\n    registry[\'runtime_directory\'] = str(synthetic_runtime)\n    registry[\'engineering_synthetic_dry_run\'] = {\'real_experiment_still_in_progress\': True, \'no_actual_job_completion\': True, \'no_actual_medical_approval\': True}\n    (mirror / registry_path).write_text(json.dumps(registry, ensure_ascii=False, indent=2) + \'\\n\')\n    result[\'synthetic_independent_jobs_marked_terminal_for_guard_only\'] = synthetic_jobs\n    env = {\'PATH\': os.environ.get(\'PATH\', \'\'), \'LANG\': \'C.UTF-8\', \'PYTHONIOENCODING\': \'utf-8\', \'PYTHONDONTWRITEBYTECODE\': \'1\'}\n    first = subprocess.run([sys.executable, str(mirror / script_path)], cwd=mirror / \'code\', env=env, capture_output=True, text=True, timeout=30)\n    stdout_logs.append(\'FIRST RUN\\nstdout:\\n\' + first.stdout + \'\\nstderr:\\n\' + first.stderr)\n    result[\'first_run_exit_code\'] = first.returncode\n    require(first.returncode == 0, \'Isolated first run failed\')\n    result[\'checks\'][\'DOCX\'] = [compare_docx(path) for path in plan_paths if path.suffix == \'.docx\']\n    result[\'checks\'][\'JSON\'] = [compare_plan_json(path) for path in plan_paths if path.suffix == \'.json\']\n    result[\'checks\'][\'CSV\'] = [compare_csv(path) for path in plan_paths if path.suffix == \'.csv\']\n    original_handoff = json.loads(original_bytes[str(handoff_path)])\n    updated_handoff = json.loads((mirror / handoff_path).read_bytes())\n    handoff_allowed = {\'prepared_at\', \'selection_optimization\', \'active_budget\', \'budget_scope\', \'pending_user_choice_historical_only\',\n                       \'no_paid_process_running_after_delivery\', \'unverified\', \'stage_passed\', \'quality_status\', \'S5_started\', \'tests_by_version\'}\n    for key in original_handoff.keys() | updated_handoff.keys():\n        if key not in handoff_allowed:\n            require(key in original_handoff and key in updated_handoff and original_handoff[key] == updated_handoff[key], f\'handoff: unexpected changed field {key}\')\n    for key, value in original_handoff.get(\'tests_by_version\', {}).items():\n        if key != \'source_selection_frozen_revision\':\n            require(updated_handoff[\'tests_by_version\'].get(key) == value, f\'handoff: historical test version altered: {key}\')\n    require(updated_handoff[\'stage_passed\'] is False and updated_handoff[\'S5_started\'] is False and updated_handoff[\'no_paid_process_running_after_delivery\'] is False, \'handoff: invalid stage/process flags\')\n    require(updated_handoff[\'selection_optimization\'][\'formal_review_progress\'] == json.loads(original_bytes[str(review_path)]), \'handoff: review record changed\')\n    result[\'checks\'][\'handoff\'] = {\'unrelated_fields_and_historical_test_versions_unchanged\': True, \'formal_review_record_preserved\': True,\n                                   \'stage_passed\': False, \'S5_started\': False, \'no_paid_process_running_after_delivery\': False}\n    before_second = tree_hashes(mirror)\n    second = subprocess.run([sys.executable, str(mirror / script_path)], cwd=mirror / \'code\', env=env, capture_output=True, text=True, timeout=30)\n    stdout_logs.append(\'SECOND RUN\\nstdout:\\n\' + second.stdout + \'\\nstderr:\\n\' + second.stderr)\n    result[\'second_run_exit_code\'] = second.returncode\n    require(second.returncode != 0 and \'Selection DOCX progress already appended\' in second.stderr, \'Duplicate run was not rejected as expected\')\n    require(before_second == tree_hashes(mirror), \'Duplicate invocation changed isolated files\')\n    result[\'checks\'][\'duplicate_rejected_without_any_mirror_file_change\'] = True\n    success = True\nexcept Exception:\n    result[\'failure\'] = traceback.format_exc()\nfinally:\n    after_hashes = {path: sha((PROJECT / path).read_bytes()) for path in original_hashes}\n    result[\'original_input_sha256_after\'] = after_hashes\n    result[\'all_original_inputs_unchanged\'] = original_hashes == after_hashes\n    result[\'original_inputs_changed\'] = [path for path in original_hashes if original_hashes[path] != after_hashes[path]]\n    production_after = production_hashes()\n    result[\'production_sources_sha256_before\'] = production_before\n    result[\'production_sources_sha256_after\'] = production_after\n    result[\'all_production_sources_unchanged\'] = production_before == production_after\n    shutil.rmtree(work)\n    result[\'temporary_directory_cleaned\'] = not work.exists()\n    result[\'passed\'] = success and result[\'all_original_inputs_unchanged\'] and result[\'all_production_sources_unchanged\'] and result[\'temporary_directory_cleaned\']\n    result[\'evidence_prefix\'] = str((OUT / label).relative_to(CODE))\n    (OUT / (label + \'.log\')).write_text(\'\\n\\n\'.join(stdout_logs) + \'\\n\' + result.get(\'failure\', \'\'), encoding=\'utf-8\')\n    (OUT / (label + \'.result.json\')).write_text(json.dumps(result, ensure_ascii=False, indent=2) + \'\\n\', encoding=\'utf-8\')\n    print(json.dumps({key: result.get(key) for key in [\'passed\', \'engineering_synthetic\', \'first_run_exit_code\', \'second_run_exit_code\', \'all_original_inputs_unchanged\', \'all_production_sources_unchanged\', \'temporary_directory_cleaned\', \'original_inputs_changed\', \'evidence_prefix\']}, ensure_ascii=False))\n    if result.get(\'failure\'):\n        print(result[\'failure\'])\nsys.exit(0 if result[\'passed\'] else 1)\n'
exec(HARNESS_SOURCE)
